<script setup lang="ts">
import { computed } from 'vue'
import { Link, router } from '@inertiajs/vue3'
import { ArrowLeft, Filter, RotateCcw } from '@lucide/vue'

interface Option { id: number; name: string; tanggal_masuk?: string | null }
interface ItemType { id: number; name: string; unit: string; category: { name: string } | null }
interface Item { item_type: ItemType | null; manual_name: string | null; quantity: number; condition: string; notes: string | null }
interface Handover { id: number; number: string; type: string; status: string; transaction_date: string; sender: Option; receiver: Option; items: Item[] }
interface Pagination { data: Handover[]; current_page: number; last_page: number }
interface Filters { date_from: string; date_to: string; type: string; status: string; sender_id: number | null; receiver_id: number | null; item_type_ids: number[] }
const props = defineProps<{ handovers: Pagination; filters: Filters; itemTypes: ItemType[]; categories: Option[]; departments: Option[]; users: Option[]; types: string[]; statuses: string[] }>()
const form = { date_from: props.filters.date_from, date_to: props.filters.date_to, type: props.filters.type, status: props.filters.status, sender_id: props.filters.sender_id ?? '', receiver_id: props.filters.receiver_id ?? '', item_type_ids: [...props.filters.item_type_ids] as number[] }
const selectedItems = computed(() => props.itemTypes.filter((item) => form.item_type_ids.includes(item.id)))
function applyFilters(): void { router.get(route('reports.index'), form, { preserveState: true, replace: true }) }
function resetFilters(): void { router.get(route('reports.index'), {}, { replace: true }) }
function toggleItem(id: number): void { form.item_type_ids = form.item_type_ids.includes(id) ? form.item_type_ids.filter((itemId) => itemId !== id) : [...form.item_type_ids, id] }
function formatDate(value: string | null | undefined): string { if (!value) return '-'; const date = value.slice(0, 10).split('-'); return date.length === 3 ? `${date[2]}-${date[1]}-${date[0]}` : value }
</script>

<template>
  <div class="min-h-screen pb-8"><header class="sticky top-0 z-10 border-b bg-white/95 px-4 py-4 backdrop-blur"><div class="mx-auto flex max-w-6xl items-center gap-3"><Link :href="route('dashboard')" class="rounded-xl p-2 text-muted-foreground hover:bg-muted"><ArrowLeft class="size-5" /></Link><div><p class="text-xs uppercase tracking-wider text-primary">SERAYA</p><h1 class="text-xl font-bold">Laporan Serah Terima</h1></div></div></header><main class="mx-auto max-w-6xl space-y-5 px-4 py-6"><section class="rounded-3xl border bg-card p-5"><div class="mb-4 flex items-center justify-between"><div><h2 class="font-semibold">Filter laporan</h2><p class="mt-1 text-sm text-muted-foreground">Pilih barang yang ingin ditampilkan dalam hasil laporan.</p></div><Filter class="size-5 text-primary" /></div><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div><label class="mb-2 block text-sm font-medium">Dari tanggal</label><input v-model="form.date_from" type="date" class="w-full rounded-xl border bg-background px-3 py-2"></div><div><label class="mb-2 block text-sm font-medium">Sampai tanggal</label><input v-model="form.date_to" type="date" class="w-full rounded-xl border bg-background px-3 py-2"></div><div><label class="mb-2 block text-sm font-medium">Jenis transaksi</label><select v-model="form.type" class="w-full rounded-xl border bg-background px-3 py-2"><option value="">Semua jenis</option><option v-for="type in types" :key="type" :value="type">{{ type }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Status</label><select v-model="form.status" class="w-full rounded-xl border bg-background px-3 py-2"><option value="">Semua status</option><option v-for="status in statuses" :key="status" :value="status">{{ status }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Pengirim</label><select v-model="form.sender_id" class="w-full rounded-xl border bg-background px-3 py-2"><option value="">Semua pengirim</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.name }}</option></select></div><div><label class="mb-2 block text-sm font-medium">Penerima</label><select v-model="form.receiver_id" class="w-full rounded-xl border bg-background px-3 py-2"><option value="">Semua penerima</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.name }}</option></select></div></div><div class="mt-4"><label class="mb-2 block text-sm font-medium">Pilih barang</label><div class="grid max-h-48 gap-2 overflow-y-auto rounded-xl border p-3 sm:grid-cols-2 lg:grid-cols-3"><label v-for="itemType in itemTypes" :key="itemType.id" class="flex cursor-pointer items-start gap-2 rounded-lg p-2 hover:bg-muted"><input type="checkbox" :checked="form.item_type_ids.includes(itemType.id)" class="mt-1 size-4 rounded" @change="toggleItem(itemType.id)"><span class="text-sm"><span class="block font-medium">{{ itemType.name }}</span><span class="text-xs text-muted-foreground">{{ itemType.category?.name ?? 'Tanpa kategori' }} · {{ itemType.unit }}</span></span></label></div><p class="mt-2 text-xs text-muted-foreground">{{ selectedItems.length }} barang dipilih. Kosongkan untuk menampilkan semua barang.</p></div><div class="mt-5 flex flex-wrap gap-2"><button type="button" class="rounded-xl bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground" @click="applyFilters">Terapkan filter</button><button type="button" class="flex items-center gap-2 rounded-xl border px-4 py-2 text-sm font-semibold" @click="resetFilters"><RotateCcw class="size-4" />Reset</button></div></section><section class="overflow-hidden rounded-3xl border bg-card"><div class="flex items-center justify-between border-b p-5"><div><h2 class="font-semibold">Hasil laporan</h2><p class="mt-1 text-sm text-muted-foreground">{{ handovers.data.length }} transaksi pada halaman ini</p></div></div><div class="overflow-x-auto"><table class="w-full min-w-[1100px] text-left text-sm"><thead class="bg-muted"><tr><th class="px-4 py-3">Tanggal</th><th class="px-4 py-3">Nomor</th><th class="px-4 py-3">Jenis</th><th class="px-4 py-3">Pengirim</th><th class="px-4 py-3">Tanggal masuk pengirim</th><th class="px-4 py-3">Penerima</th><th class="px-4 py-3">Tanggal masuk penerima</th><th class="px-4 py-3">Barang</th><th class="px-4 py-3">Status</th></tr></thead><tbody class="divide-y"><tr v-for="handover in handovers.data" :key="handover.id"><td class="px-4 py-3">{{ formatDate(handover.transaction_date) }}</td><td class="px-4 py-3 font-medium">{{ handover.number }}</td><td class="px-4 py-3">{{ handover.type }}</td><td class="px-4 py-3">{{ handover.sender.name }}</td><td class="px-4 py-3">{{ formatDate(handover.sender.tanggal_masuk) }}</td><td class="px-4 py-3">{{ handover.receiver.name }}</td><td class="px-4 py-3">{{ formatDate(handover.receiver.tanggal_masuk) }}</td><td class="px-4 py-3"><div class="space-y-1"><div v-for="item in handover.items" :key="`${item.item_type?.name ?? item.manual_name}-${item.quantity}`">{{ item.item_type?.name ?? item.manual_name }} × {{ item.quantity }} {{ item.item_type?.unit ?? '' }}</div></div></td><td class="px-4 py-3"><span class="rounded-full bg-amber-100 px-2 py-1 text-xs font-medium text-amber-700">{{ handover.status }}</span></td></tr><tr v-if="!handovers.data.length"><td colspan="9" class="px-4 py-10 text-center text-muted-foreground">Tidak ada data sesuai filter.</td></tr></tbody></table></div></section></main></div>
</template>
